import re


def safe_sql(sql, allowed, limit=100):
    sql = sql.strip()
    if sql.endswith(";"):
        sql = sql[:-1].strip()
    if ";" in sql:
        return [False, "multiple statements"]
    if not re.match(r"(select|with)\b", sql, re.I):
        return [False, "only SELECT"]
    if re.search(r"\b(insert|update|delete|drop|alter|create|copy|attach|pragma|install|load)\b", sql, re.I):
        return [False, "write keyword"]
    ctes = {c.lower() for c in re.findall(r"(\w+)\s+as\s*\(", sql, re.I)}
    for t in re.findall(r"\b(?:from|join)\s+([a-zA-Z_][\w.]*)", sql, re.I):
        if t.lower() not in allowed and t.lower() not in ctes:
            return [False, "table not allowed: " + t.lower()]
    if not re.search(r"\blimit\s+\d+", sql, re.I):
        sql += " LIMIT " + str(limit)
    return [True, sql]

